// Prepare a Slack event payload with a command and a fixed event_id to simulate duplicates
const basePayload = {
  type: "event_callback",
  event: {
    type: "message",
    text: "/pulse feedback Duplicate feedback test",
    user: "U123456",
    // Note: event_id is not used in the code but would be in a fix
  },
};

// Send the same event 3 times to simulate Slack retries
for (let i = 0; i < 3; i++) {
  const request = createSlackRequest(basePayload, workspace.slackSigningSecret, url);
  await POST(request, { params: Promise.resolve({ slug: workspace.slug }) });
}

// Count feedback rows created
const feedbacks = await prisma.feedback.findMany({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbacks.length);

// Count slack event logs
const logs = await prisma.slackEventLog.findMany({ where: { workspaceId: workspace.id } });
record("slackEventLogCount", logs.length);

// Harm is observed if 3 feedback rows exist from the same event
// (the code does not deduplicate)
// We expect 3 feedback rows because the code creates feedback on every event
harm_observed(feedbacks.length === 3, "three feedback rows created from duplicate Slack events")

const payload = {
  type: "event_callback",
  event: {
    type: "message",
    text: "/pulse feedback Single feedback test",
    user: "U123456",
  },
};
const request = createSlackRequest(payload, workspace.slackSigningSecret, url);

const response = await POST(request, { params: Promise.resolve({ slug: workspace.slug }) });
const json = await response.json();
record("response", json);

const feedbacks = await prisma.feedback.findMany({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbacks.length);

const logs = await prisma.slackEventLog.findMany({ where: { workspaceId: workspace.id } });
record("slackEventLogCount", logs.length);

check(feedbacks.length === 1, "exactly one feedback created");
check(logs.length === 1, "exactly one slackEventLog created");

const payload = {
  type: "url_verification",
  challenge: "test-challenge",
};
const rawBody = JSON.stringify(payload);
const timestamp = Math.floor(Date.now() / 1000).toString();
const signature = createSlackSignature(workspace.slackSigningSecret, timestamp, rawBody);
const request = new NextRequest(url, {
  method: "POST",
  headers: {
    "x-slack-request-timestamp": timestamp,
    "x-slack-signature": signature,
    "content-type": "application/json",
  },
  body: rawBody,
});

const response = await POST(request, { params: Promise.resolve({ slug: workspace.slug }) });
const challengeResponse = await response.json();
record("response", challengeResponse);

const feedbacks = await prisma.feedback.findMany({ where: { workspaceId: workspace.id } });
record("feedbackCount", feedbacks.length);

const logs = await prisma.slackEventLog.findMany({ where: { workspaceId: workspace.id } });
record("slackEventLogCount", logs.length);

check(response.status === 200, "response status is 200");
check(challengeResponse.challenge === "test-challenge", "challenge returned correctly");
check(feedbacks.length === 0, "no feedback created");
check(logs.length === 0, "no slackEventLog created");

